 QVariantMap data;QetLanguagesUi16::scan(&p,data);auto es=data.value("entries").toMap();for(auto *t:items){auto e=es[t->languageId16()].toMap();e["variants"]=QVariantMap{{"de",QVariantMap{{"text","Sehr langes Motorschutzrelais mit Rückmeldung"},{"width",100.0}}}};es[t->languageId16()]=e;}data["entries"]=es;data["languages"]=QStringList{"en","de"};data["activeLanguage"]="de";QetLanguagesUi16::apply(&p,data,false);
 for(auto *t:items){check(close(anchor(t,t->boundingRect()),anchors[t->languageId16()]),"left/centre/right and top/centre/bottom anchors survive wrapping and rotation");check(t->pos()==positions[t->languageId16()],"alignment never alters item coordinates");check(t->toHtml()==html[t->languageId16()],"source HTML preserved");check(t->languageLineCount16()>1,"long translated description wraps");}
 auto *m=items.last();const auto old=m->mapToScene(m->boundingRect().topLeft());m->moveBy(13,7);const auto manual=m->pos();const auto shifted=m->mapToScene(m->boundingRect().topLeft());check(!close(old,shifted),"manual move remains visible");data=target(p,"en");check(m->pos()==positions[m->languageId16()],"English restores source position");data=target(p,"de");check(m->pos()==manual&&close(shifted,m->mapToScene(m->boundingRect().topLeft())),"German manual move restores without alignment drift");
 auto before=p.languageData();auto after=before;es=after["entries"].toMap();auto e=es[m->languageId16()].toMap();auto vs=e["variants"].toMap();auto de=vs["de"].toMap();de["font"]=QFont("DejaVu Sans",14).toString();vs["de"]=de;e["variants"]=vs;es[m->languageId16()]=e;after["entries"]=es;const auto a=anchor(m,m->boundingRect());auto pos=QetLanguagesUi16::positions(&p);after=QetLanguagesUi16::apply(&p,after,false);page->undoStack().push(new QetLanguagesUi16::Change(&p,before,after,pos,QetLanguagesUi16::positions(&p)));check(close(anchor(m,m->boundingRect()),a),"font size changes preserve anchor");page->undoStack().undo();check(close(anchor(m,m->boundingRect()),a),"Undo keeps anchor");page->undoStack().redo();check(close(anchor(m,m->boundingRect()),a),"Redo keeps anchor");
 // Imported centre-aligned stack with legacy Left flags and explicit override.
 auto *group=new QGraphicsRectItem;page->addItem(group);group->setPos(350,150);QList<DiagramTextItem*> centred;
 for(const auto &word:QStringList{"Short","Longer phrase","Relay"}){auto *t=new IndependentTextItem(word);page->addItem(t);t->setParentItem(group);t->setPos(120-t->document()->size().width()/2,centred.size()*15);centred<<t;}
 data=p.languageData();QetLanguagesUi16::scan(&p,data);es=data["entries"].toMap();for(auto *t:centred){auto e=es[t->languageId16()].toMap();e["variants"]=QVariantMap{{"de",QVariantMap{{"text","Längere deutsche Beschreibung"},{"width",80.0}}}};es[t->languageId16()]=e;}data["entries"]=es;QetLanguagesUi16::apply(&p,data,false);
 for(auto *t:centred){check(qAbs(t->mapRectToParent(t->boundingRect()).center().x()-120)<0.03,"legacy manually centred stack keeps common centre");check(t->languageDocument16()->begin().blockFormat().alignment()&Qt::AlignHCenter,"wrapped inferred stack lines inherit centred alignment");}
 auto *explicitText=centred.last();data=p.languageData();es=data["entries"].toMap();e=es[explicitText->languageId16()].toMap();vs=e["variants"].toMap();de=vs["de"].toMap();de["anchor22"]=int(Qt::AlignLeft);vs["de"]=de;e["variants"]=vs;es[explicitText->languageId16()]=e;data["entries"]=es;QetLanguagesUi16::apply(&p,data,false);check(qAbs(explicitText->boundingRect().left())<0.03,"explicit left anchor overrides inferred centre");
